from fractions import Fraction as Q
from itertools import product, combinations

def replay(document):
    count=0; output={}
    def ck(ok):
        nonlocal count
        assert ok
        count+=1
    def canonical_columns(n):
        return [g for g in product(range(1,n+1),repeat=n) if set(g)==set(range(1,max(g)+1))]
    for case in document['cases']:
        n,D=case['n'],case['D'];pairs=list(combinations(range(n),2));M=len(pairs)
        w=list(map(Q,case['weights']));tau=list(map(Q,case['tau']))
        states=[(st['theta'],Q(st['mass'])) for st in case['states']]
        ck(sum(p for _,p in states)==1 and all(p>0 for _,p in states))
        ck(sum(w)==1 and all(x>=0 for x in w) and all(0<x<=Q(1,2) for x in tau))
        ck(all(len(t)==n and all(len(row)==D for row in t) for t,_ in states))
        ck(all(len({t[i][d] for i in range(n)})==n for t,_ in states for d in range(D)))
        def encode(columns):
            return tuple(1 if g[i]<g[j] else -1 if g[i]>g[j] else 0 for g in columns for i,j in pairs)
        cols=canonical_columns(n)
        grade_actions={encode(gs):gs for gs in product(cols,repeat=D)}
        common_actions={encode([g]*D) for g in cols}
        ck(len(grade_actions)==len(cols)**D and len(common_actions)==len(cols))
        ck(len(cols)==case['expected_canonical_columns'])
        def poset(action):
            for d in range(D):
                relation=set()
                for z,(i,j) in zip(action[d*M:(d+1)*M],pairs):
                    if z:relation.add((i,j) if z==1 else (j,i))
                if any((i,k) not in relation for i,j in relation for jj,k in relation if j==jj):return False
            return True
        rows=[]
        for action in product((-1,0,1),repeat=D*M):
            N=[sum(z!=0 for z in action[d*M:(d+1)*M]) for d in range(D)]
            risk=Q(0);joint=Q(0)
            for theta,mass in states:
                F=[0]*D
                for d in range(D):
                    for z,(i,j) in zip(action[d*M:(d+1)*M],pairs):
                        if z==1:F[d]+=theta[i][d]<=theta[j][d]
                        elif z==-1:F[d]+=theta[j][d]<=theta[i][d]
                ck(all(0<=F[d]<=N[d]<=M for d in range(D)))
                risk+=mass*sum(w[d]*(F[d]+tau[d]*(M-N[d]))/M for d in range(D))
                joint+=mass*int(any(F))
            mem={'C':action in common_actions,'P':action in grade_actions,'O':poset(action),'F':True}
            ck(not mem['C'] or mem['P']);ck(not mem['P'] or mem['O'])
            rows.append({'action':list(action),'N':N,'risk':str(risk),'J':str(joint),'family_membership':mem})
        ck(len(rows)==3**(D*M))
        zero=next(r for r in rows if not any(r['action']))
        baseline=sum(a*b for a,b in zip(w,tau));ck(Q(zero['risk'])==baseline and Q(zero['J'])==0)
        budgets=[]
        for budget in case['budgets']:
            alpha=Q(budget['alpha']);families={}
            for family in ['C','P','O','F']:
                allowed=[r for r in rows if r['family_membership'][family]]
                feasible=[r for r in allowed if Q(r['J'])<=alpha]
                ck(bool(feasible))
                best=min(Q(r['risk']) for r in feasible)
                winners=[r['action'] for r in feasible if Q(r['risk'])==best]
                ck(best==Q(case['expected_minimum_risks'][family]))
                ck(len(winners)==case['expected_minimizer_counts'][family])
                families[family]={'allowed_count':len(allowed),'feasible_count':len(feasible),'minimum_risk':str(best),'minimizers':winners}
            vals=[Q(families[k]['minimum_risk']) for k in ['F','O','P','C']]
            ck(0<=vals[0]<=vals[1]<=vals[2]<=vals[3]<=baseline)
            gap=Q(families['P']['minimum_risk'])-Q(families['F']['minimum_risk'])
            ck(gap==Q(case['expected_product_free_gap']))
            ck(families['F']['minimizers']==[case['expected_free_action']])
            if case['id'].startswith('ADJACENT'):
                ck(alpha<Q(1,n))
                ck(families['P']['minimizers']==[[0]*M])
                ck(families['F']['minimizers']==families['O']['minimizers'])
                ck(tuple(case['expected_free_action']) not in grade_actions)
                ck(gap==tau[0]*(1-Q(2,n))<tau[0])
            budgets.append({'id':budget['id'],'alpha':str(alpha),'families':families,'product_free_gap':str(gap)})
        if case['id'].startswith('ADJACENT'):
            # Independently verify the full advertised error pattern in the actual coherent states.
            for i,j in pairs:
                forward_error=sum(mass*int(theta[i][0]<=theta[j][0]) for theta,mass in states)
                ck(forward_error==(Q(1,n) if j==i+1 else Q(0)))
            # A two-block cut has exactly one uncertain adjacent edge, giving the stated alpha boundary.
            for k in range(1,n):
                g=tuple(1 if i<k else 2 for i in range(n));a=encode([g])
                r=next(r for r in rows if r['action']==list(a));ck(Q(r['J'])==Q(1,n))
        output[case['id']]={'M':M,'canonical_columns':len(cols),'pair_order_zero_based':[list(z) for z in pairs],
          'action_layout':'domain-major then lexicographic unordered pairs; +1 first unit higher, -1 second higher, 0 withhold',
          'all_action_rows':rows,'budgets':budgets}
    return {'status':'PASS','assertions':count,'arithmetic':'fractions.Fraction; exact finite laws; exhaustive bounded action families','case_count':len(document['cases']),'results':output}
